import { Component, Inject, Input, LOCALE_ID, OnChanges } from '@angular/core';

import _ from 'lodash';

@Component({
  selector: 'cd-usage-bar',
  templateUrl: './usage-bar.component.html',
  styleUrls: ['./usage-bar.component.scss']
})
export class UsageBarComponent implements OnChanges {
  @Input()
  total: number;
  @Input()
  used: any;
  @Input()
  warningThreshold?: number;
  @Input()
  errorThreshold?: number;
  @Input()
  isBinary = true;
  @Input()
  decimals = 0;
  @Input()
  calculatePerc = true;
  @Input()
  title = $localize`usage`;
  @Input()
  customLegend?: string;
  @Input()
  customLegendValue?: string;
  @Input()
  showFreeToolTip = true;
  @Input()
  showMultisiteTooltip = false;

  usedPercentage: number;
  freePercentage: number;

  isZhHans: boolean;

  get usedLabel(): string {
    return this.isZhHans ? '已用:' : 'Used:';
  }

  get freeLabel(): string {
    return this.isZhHans ? '可用:' : 'Free:';
  }

  get totalShardsLabel(): string {
    return this.isZhHans ? '分片总数:' : 'Total Shards:';
  }

  get transferredShardsLabel(): string {
    return this.isZhHans ? '已传输分片:' : 'Transferred Shards:';
  }

  constructor(@Inject(LOCALE_ID) localeId: string) {
    this.isZhHans = localeId.startsWith('zh');
  }

  ngOnChanges() {
    if (this.calculatePerc) {
      this.usedPercentage = this.total > 0 ? (this.used / this.total) * 100 : 0;
      this.freePercentage = 100 - this.usedPercentage;
    } else {
      if (this.used) {
        this.used = this.used.slice(0, -1);
        this.usedPercentage = Number(this.used);
        this.freePercentage = 100 - this.usedPercentage;
      } else {
        this.usedPercentage = 0;
      }
    }
  }
}
